 const onQrScanned=async({data}:{data:string})=>{if(scanLock.current)return;const value=typeof data==='string'?data.trim():'';if(!value){setFriendError('This QR code has no readable Wantiss ID.');return;}scanLock.current=true;setFriendError('Reading Wantiss QR…');try{const tokenMatch=value.match(/^wantiss:\/\/qr\?token=([A-Za-z0-9_-]{32,256})$/i);if(tokenMatch){const {data:identity,error}=await supabase.rpc('resolve_qr_identity',{p_token:tokenMatch[1]});if(error)throw error;if(!identity?.valid)throw new Error('This Wantiss QR is invalid or no longer active.');if(identity.destination!=='buyer-profile'||!identity.owner_user_id)throw new Error('Scan a personal Wantiss ID QR code to add a friend.');setScannedFriendId(identity.owner_user_id);setFriendQuery(identity.wantiss_number||identity.display_name||'Wantiss member');const {data:existing}=await supabase.from('user_friendships').select('id,requester_id,recipient_id,status').or(`and(requester_id.eq.${currentUserId},recipient_id.eq.${identity.owner_user_id}),and(requester_id.eq.${identity.owner_user_id},recipient_id.eq.${currentUserId})`).in('status',['pending','accepted']).limit(1).maybeSingle();setPersonPreview({id:identity.owner_user_id,name:identity.display_name||'Wantiss member',avatar:identity.avatar_url||null,number:identity.wantiss_number||null,bio:identity.bio||null,membershipTier:identity.membership_tier||null,status:existing?.status||'none',requestId:existing?.id||null,isRequester:existing?.requester_id===currentUserId});setFriendError('');setScannerOpen(false);setPanel('person');void loadPersonExtras(identity.owner_user_id);return;}let parsed=value;try{const json=JSON.parse(value);parsed=String(json.wantiss_number||json.wantissId||json.wantiss_id||json.user_id||json.id||value);}catch{}const match=parsed.match(/(?:wantiss:\/\/user\/|wantiss:\/\/profile\/|wantiss\.app\/u\/|wantiss\.app\/profile\/)([A-Za-z0-9_+%-]+)/i);let resolved=match?match[1]:parsed;try{resolved=decodeURIComponent(resolved);}catch{}setScannedFriendId(null);setFriendQuery(resolved);setFriendError('QR code scanned. Review the ID and send your friend request.');setScannerOpen(false);}catch(e){setFriendError(e instanceof Error?e.message:'Could not verify this Wantiss QR code.');}finally{scanLock.current=false;}};
 const scanFromPhotos=async()=>{setScanBusy(true);try{const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],allowsEditing:false,quality:1});if(!result.canceled&&result.assets[0]?.uri){const found=await scanFromURLAsync(result.assets[0].uri,['qr']);if(found?.length&&typeof found[0]?.data==='string')await onQrScanned({data:found[0].data});else setFriendError('No QR code detected in this image. Try a clearer picture.');}}catch(e){setFriendError(e instanceof Error?e.message:'Unable to read the selected QR image.');}finally{setScanBusy(false);}};
 const cancelFriendRequest=async()=>{if(!personPreview?.requestId||!personPreview.isRequester)return;const {error}=await supabase.from('user_friendships').delete().eq('id',personPreview.requestId).eq('requester_id',currentUserId).eq('status','pending');if(error){setFriendError(error.message);return;}setPersonPreview(p=>p?{...p,status:'none',requestId:null,isRequester:false}:p);setFriendError('Request cancelled.');};
 const deletePendingRequest=async(id:string)=>{const {data,error}=await supabase.from('user_friendships').delete().eq('id',id).eq('requester_id',currentUserId).eq('status','pending').select('id').maybeSingle();if(error){setFriendError(error.message);return;}if(!data){setFriendError('This request is no longer pending.');await openPanel('addFriend');return;}setFriendships(prev=>prev.filter(f=>f.id!==id));setFriendError('Friend request deleted.');setPersonPreview(prev=>prev?.requestId===id?{...prev,status:'none',requestId:null,isRequester:false}:prev);};
 const loadPersonExtras=async(id:string)=>{const [{data:moments,error:momentError},{data:follow},{data:privacy}]=await Promise.all([supabase.rpc('wantiss_get_person_moments',{p_user_id:id}),supabase.from('wantiss_follows').select('follower_id').eq('follower_id',currentUserId).eq('followed_id',id).maybeSingle(),supabase.from('wantiss_contact_visibility').select('hide_my_moments,hide_their_moments').eq('owner_id',currentUserId).eq('contact_id',id).maybeSingle()]);const visible=momentError?[]:moments||[];const signed=await Promise.all(visible.map(async(m:any)=>{if(!m.media_path)return m;const {data}=await supabase.storage.from('wantiss-moments').createSignedUrl(m.media_path,120);return {...m,image_url:data?.signedUrl||null};}));setPersonMoments(signed);setIsFollowing(!!follow);const [{count:followers},{count:following}]=await Promise.all([supabase.from('wantiss_follows').select('follower_id',{count:'exact',head:true}).eq('followed_id',id),supabase.from('wantiss_follows').select('followed_id',{count:'exact',head:true}).eq('follower_id',id)]);setFollowCounts({followers:followers||0,following:following||0});setContactPrivacy({hide_my_moments:!!privacy?.hide_my_moments,hide_their_moments:!!privacy?.hide_their_moments});};
