 const chooseMomentPhoto=async()=>{const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],allowsEditing:false,quality:0.8});if(result.canceled||!result.assets[0])return;const asset=result.assets[0];if(asset.fileSize&&asset.fileSize>10*1024*1024){setFriendError('Choose a photo smaller than 10 MB.');return;}setMomentPhoto({uri:asset.uri,mimeType:asset.mimeType==='image/png'?'image/png':asset.mimeType==='image/webp'?'image/webp':'image/jpeg'});};
 const publishMoment=async()=>{if(!currentUserId||(!momentDraft.trim()&&!momentPhoto)||profileBusy)return;setProfileBusy(true);setFriendError('');let mediaPath:string|null=null;try{if(momentPhoto){const file=new ExpoFile(momentPhoto.uri);const bytes=await file.arrayBuffer();if(bytes.byteLength>10*1024*1024)throw new Error('Photo must be smaller than 10 MB.');mediaPath=`${currentUserId}/${Date.now()}-${Math.random().toString(36).slice(2)}.${momentPhoto.mimeType==='image/png'?'png':momentPhoto.mimeType==='image/webp'?'webp':'jpg'}`;const {error:uploadError}=await supabase.storage.from('wantiss-moments').upload(mediaPath,bytes,{contentType:momentPhoto.mimeType,upsert:false});if(uploadError)throw uploadError;}const {error}=await supabase.from('wantiss_moments').insert({user_id:currentUserId,body:momentDraft.trim(),media_path:mediaPath});if(error)throw error;setMomentDraft('');setMomentPhoto(null);void loadPersonExtras(currentUserId);}catch(e){if(mediaPath)void supabase.storage.from('wantiss-moments').remove([mediaPath]);setFriendError(e instanceof Error?e.message:'Unable to publish Moment.');}finally{setProfileBusy(false);}};
 const messageFriend=async(id:string)=>{if(!currentUserId)return;const {data:relations,error:relationError}=await supabase.from('user_friendships').select('id').eq('status','accepted').or(`and(requester_id.eq.${currentUserId},recipient_id.eq.${id}),and(requester_id.eq.${id},recipient_id.eq.${currentUserId})`).limit(1);if(relationError||!relations?.length){setFriendError('You must be friends before messaging.');return;}const {data:existing,error:existingError}=await supabase.from('conversations').select('id,title,participant_ids,updated_at,feature,ref_id,business_id,customer_id').eq('feature','friends').contains('participant_ids',[currentUserId,id]).limit(1).maybeSingle();if(existingError){setFriendError(existingError.message);return;}let conversation=existing as Conversation|null;if(!conversation){const {data:created,error}=await supabase.from('conversations').insert({participant_ids:[currentUserId,id],customer_id:currentUserId,feature:'friends',status:'active',title:friendDisplayName(id)}).select('id,title,participant_ids,updated_at,feature,ref_id,business_id,customer_id').single();if(error){setFriendError(error.message);return;}conversation=created as Conversation;}setPanel('inbox');await openConversation(conversation);};
 const friendDisplayName=(id:string)=>{const p=contactProfiles[id];return p?.full_name?.trim()||p?.wantiss_number?.trim()||'Wantiss member';};
 const conversationDisplayName=(c:Conversation)=>{if(c.feature!=='friends')return c.title||'Wantiss conversation';const peer=c.participant_ids?.find(id=>id!==currentUserId);return peer?friendDisplayName(peer):(c.title||'Wantiss conversation');};
 const viewContact=async(id:string,status:string)=>{const p=contactProfiles[id];const friendship=friendships.find(f=>f.requester_id===id||f.recipient_id===id);setScannedFriendId(null);setPersonPreview({id,name:friendDisplayName(id),avatar:p?.avatar_url||null,number:p?.wantiss_number||null,bio:null,status,requestId:friendship?.id||null,isRequester:friendship?.requester_id===currentUserId});setPanel('person');setFriendError('');void loadPersonExtras(id);};
